CREATE DATABASE IF NOT EXISTS renwei_script CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE renwei_script;
CREATE TABLE IF NOT EXISTS clients (id CHAR(36) NOT NULL PRIMARY KEY, name VARCHAR(255) NOT NULL, industry VARCHAR(100), description TEXT, status ENUM('active','archived') NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS accounts (id CHAR(36) NOT NULL PRIMARY KEY, client_id CHAR(36) NOT NULL, name VARCHAR(255) NOT NULL, platform VARCHAR(50), account_type VARCHAR(100), ip_role VARCHAR(100), account_url TEXT, status ENUM('active','archived') NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_accounts_client FOREIGN KEY (client_id) REFERENCES clients(id), INDEX idx_accounts_client (client_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS source_documents (id CHAR(36) NOT NULL PRIMARY KEY, client_id CHAR(36) NOT NULL, account_id CHAR(36), file_name VARCHAR(500) NOT NULL, file_type VARCHAR(50), storage_path TEXT NOT NULL, source_type VARCHAR(100), source_date DATE, content_hash VARCHAR(128), extraction_status ENUM('pending','processing','completed','failed') NOT NULL DEFAULT 'pending', raw_text LONGTEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_source_documents_client FOREIGN KEY (client_id) REFERENCES clients(id), CONSTRAINT fk_source_documents_account FOREIGN KEY (account_id) REFERENCES accounts(id), INDEX idx_source_documents_client (client_id), INDEX idx_source_documents_account (account_id), INDEX idx_source_documents_hash (content_hash)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS fact_items (id CHAR(36) NOT NULL PRIMARY KEY, client_id CHAR(36) NOT NULL, account_id CHAR(36), source_document_id CHAR(36), category VARCHAR(100) NOT NULL, title VARCHAR(255) NOT NULL, fact_text TEXT NOT NULL, fact_type ENUM('confirmed','pending','inference','prohibited') NOT NULL DEFAULT 'pending', evidence_text TEXT, source_locator JSON, permission_status ENUM('unknown','internal_only','public_usable','restricted') NOT NULL DEFAULT 'unknown', usable_for_script BOOLEAN NOT NULL DEFAULT TRUE, tags JSON, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_fact_items_client FOREIGN KEY (client_id) REFERENCES clients(id), CONSTRAINT fk_fact_items_account FOREIGN KEY (account_id) REFERENCES accounts(id), CONSTRAINT fk_fact_items_source FOREIGN KEY (source_document_id) REFERENCES source_documents(id), INDEX idx_fact_items_client (client_id), INDEX idx_fact_items_account (account_id), INDEX idx_fact_items_type (fact_type), FULLTEXT KEY ft_fact_items_text (title, fact_text, evidence_text)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS logic_patterns (id CHAR(36) NOT NULL PRIMARY KEY, benchmark_video_id CHAR(36), industry VARCHAR(100), account_type VARCHAR(100), pattern_name VARCHAR(255) NOT NULL, applicable_goals JSON, audience_emotion VARCHAR(100), core_mechanism TEXT, structure_summary TEXT, opening_pattern TEXT, conflict_pattern TEXT, proof_pattern TEXT, transition_pattern TEXT, cta_pattern TEXT, reusable_template TEXT, limitations TEXT, evidence_status ENUM('confirmed','pending','inference') NOT NULL DEFAULT 'pending', tags JSON, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_logic_patterns_industry (industry), INDEX idx_logic_patterns_account_type (account_type), INDEX idx_logic_patterns_status (evidence_status), FULLTEXT KEY ft_logic_patterns_text (pattern_name, core_mechanism, structure_summary, reusable_template)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS script_goals (id CHAR(36) NOT NULL PRIMARY KEY, client_id CHAR(36) NOT NULL, account_id CHAR(36), ip_role VARCHAR(100), goal_type VARCHAR(100) NOT NULL, topic VARCHAR(500), target_audience TEXT, audience_pain_points JSON, desired_action TEXT, platform VARCHAR(50), duration_seconds INT, shooting_constraints JSON, tone_requirements JSON, must_include JSON, must_avoid JSON, status ENUM('draft','ready','generating','completed','cancelled') NOT NULL DEFAULT 'draft', version INT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_script_goals_client FOREIGN KEY (client_id) REFERENCES clients(id), CONSTRAINT fk_script_goals_account FOREIGN KEY (account_id) REFERENCES accounts(id), INDEX idx_script_goals_client (client_id), INDEX idx_script_goals_account (account_id), INDEX idx_script_goals_type (goal_type), INDEX idx_script_goals_status (status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
